'use strict';
const form=document.querySelector('#capture-form');
form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button');const status=document.querySelector('#capture-status');button.disabled=true;status.textContent='Enviando…';try{const fields=Object.fromEntries(new FormData(form));fields.consent=form.elements.consent.checked;const res=await fetch('/api/capture/'+encodeURIComponent(form.dataset.page),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(fields)});const data=await res.json();if(!res.ok)throw new Error(data.error||'Não foi possível enviar.');form.reset();status.textContent='Recebemos seu interesse. Obrigado!';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
